'use strict';
let inputSource='manual',simbriefPlan=null,manualDraft=null,simbriefDraft=null,profileCache=null,importController=null,importVersion=0;
function routePoint(fraction){return flight?.route?SimBrief.position(flight.route,fraction,interpolate):interpolate(flight.a,flight.b,fraction);}
function importedAirport(point){const known=airport(point.code);return {...point,city:known?.city||point.name,tz:known?.tz||aircraftPositionClock(simbriefPlan.takeoff,point.lat,point.lon).zone};}
function prepareImportedFlight(){
 if(!simbriefPlan)throw Error('Import a SimBrief OFP first.');
 if(!simbriefPlan.routeAvailable&&!$('directFallback').checked)throw Error('This OFP has no timed route. Select the direct-route fallback to continue.');
 const a=importedAirport(simbriefPlan.origin),b=importedAirport(simbriefPlan.destination);let start=localUTC($('date').value,$('time').value,a.tz);
 if(Math.floor(simbriefPlan.takeoff/60000)===Math.floor(start/60000))start=simbriefPlan.takeoff;
 const route=simbriefPlan.routeAvailable?simbriefPlan:null,directDist=angle(a,b)*6371,dist=route?route.fixes.slice(1).reduce((sum,p,i)=>sum+angle(route.fixes[i],p)*6371,0):directDist;
 return {a,b,start,ms:simbriefPlan.durationSec*1000,route,dist,directDist};
}
function syncSourceUI(){const imported=inputSource==='simbrief';$('simbriefPanel').hidden=!imported;$('manualRouteFields').hidden=imported;$('manualRouteFields').disabled=imported;$('manualTimingFields').hidden=imported;$('manualTimingFields').disabled=imported;document.querySelector('.presets').hidden=imported;document.querySelectorAll('[data-source]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.source===inputSource)));$('departureDateLabel').textContent=imported?'TAKEOFF DATE':'DEPARTURE DATE';$('departureTimeLabel').replaceChildren(document.createTextNode(imported?'TAKEOFF TIME ':'DEPARTURE TIME '),Object.assign(document.createElement('span'),{className:'subtle',textContent:'local at origin'}));$('departureMetricLabel').textContent=imported?'Estimated takeoff':'Scheduled departure';renderImportSummary();}
function switchSource(next){if(next===inputSource)return;importVersion++;importController?.abort();cancelPicking();closeCalendar();closeTimePicker();pause();if(inputSource==='manual')manualDraft=formState();else simbriefDraft=formState();inputSource=next;if(next==='manual'&&manualDraft)restoreForm(manualDraft);else if(next==='simbrief'&&simbriefPlan){if(simbriefDraft)restoreForm(simbriefDraft);else resetImportedTime();}syncSourceUI();if(next==='manual'||simbriefPlan)calculate();else{$('error').textContent='Import a SimBrief flight to replace the current manual preview.';$('simulationNotice').hidden=false;$('simulationNotice').textContent='Showing the manual preview until a SimBrief flight is imported.';}}
function resetImportedTime(){if(!simbriefPlan)return;const a=importedAirport(simbriefPlan.origin);$('date').value=isoDateInZone(simbriefPlan.takeoff,a.tz);setDepartureTime(clock(simbriefPlan.takeoff,a.tz));updateDateButton();$('zone').textContent=`${a.tz.replaceAll('_',' ')} · Estimated takeoff; edit to explore another departure.`;}
function renderImportSummary(){const p=simbriefPlan;$('simbriefSummary').hidden=!p;if(!p)return;$('simbriefFlight').textContent=`${p.callsign?p.callsign+' · ':''}${p.origin.code} → ${p.destination.code}`;$('simbriefTiming').textContent=`Takeoff ${dateLabel(p.takeoff)} ${clock(p.takeoff)} UTC · ${duration(p.durationSec*1000)} airborne`;$('simbriefMeta').textContent=`${p.aircraft||'Aircraft unspecified'} · ${Math.max(0,p.fixes.length-2)} timed fixes${p.airac?' · AIRAC '+p.airac:''}`;$('simbriefWarnings').replaceChildren(...(p.warnings||[]).map(w=>Object.assign(document.createElement('li'),{textContent:w})));$('directFallbackWrap').hidden=p.routeAvailable;}
function acceptSimbriefPlan(p){SimBrief.validate(p);simbriefPlan=p;$('directFallback').checked=false;simbriefDraft=null;resetImportedTime();renderImportSummary();$('simbriefError').textContent='';calculate();if(!$('error').textContent)toast('SimBrief flight imported. Playback starts at takeoff.');}
async function importLatestSimbrief(){const identity=$('simbriefIdentity').value.trim(),kind=$('simbriefIdentityType').value;if(!identity||identity.length>100||kind==='userid'&&!/^\d{1,7}$/.test(identity)){$('simbriefError').textContent='Enter a Navigraph alias or a 1–7 digit Pilot ID.';return;}const button=$('importSimbrief');button.disabled=true;button.textContent='Importing…';$('simbriefError').textContent='';const controller=new AbortController(),version=++importVersion;importController?.abort();importController=controller;const timer=setTimeout(()=>controller.abort(),20000);try{const url=new URL('https://www.simbrief.com/api/xml.fetcher.php');url.searchParams.set(kind,identity);url.searchParams.set('client','Dayflight-1.0');url.searchParams.set('json','v2');const response=await fetch(url,{signal:controller.signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'}),raw=await response.text();if(raw.length>12*1024*1024)throw Error('OFP exceeds the 12 MB import limit.');if(!response.ok){let message='SimBrief could not find a generated flight for this alias/ID.';try{const error=JSON.parse(raw);message=error.fetch?.status||message;}catch{}throw Error(message);}if(version===importVersion&&inputSource==='simbrief')acceptSimbriefPlan(SimBrief.parse(raw));}catch(e){if(version!==importVersion)return;$('simbriefError').textContent=e.name==='AbortError'?'SimBrief timed out. Try again or import an OFP file.':e instanceof TypeError?'Cannot reach SimBrief from this browser. Check your connection, or import the OFP JSON/XML file.':e.message;}finally{clearTimeout(timer);button.disabled=false;button.textContent='Import latest flight ↓';}}
function planState(portable=false){let state=formState();if(portable&&inputSource==='simbrief'&&simbriefPlan)state={from:simbriefPlan.origin.code,to:simbriefPlan.destination.code,date:$('date').value,time:$('time').value,duration:String(simbriefPlan.durationSec/3600),mode:'duration',clockPrefs:{from:{mode:'auto',offset:''},to:{mode:'auto',offset:''}},speedUnit:'knots',custom:null,customFrom:null};return {...state,source:inputSource,simbrief:portable&&inputSource==='manual'?null:simbriefPlan,...(portable?{}:{manualDraft,simbriefDraft}),showDirect:$('showDirect').checked,directFallback:$('directFallback').checked};}
function downloadPlan(){const blob=new Blob([JSON.stringify(planState(true),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dayflight-${flight.a.code}-${flight.b.code}-plan.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function restore(state){const validated=state.simbrief?SimBrief.validate(state.simbrief):null;restoreForm(state);manualDraft=state.manualDraft||null;simbriefDraft=state.simbriefDraft||null;simbriefPlan=validated;inputSource=state.source==='simbrief'&&simbriefPlan?'simbrief':'manual';$('showDirect').checked=state.showDirect!==false;$('directFallback').checked=state.directFallback===true;syncSourceUI();}
function initSimbriefUI(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>switchSource(b.dataset.source));$('importSimbrief').onclick=importLatestSimbrief;$('importOfpFile').onclick=()=>$('ofpFile').click();$('ofpFile').onchange=async()=>{const file=$('ofpFile').files[0],version=++importVersion;if(!file)return;try{importController?.abort();if(file.size>12*1024*1024)throw Error('Choose an OFP under 12 MB.');const raw=await file.text();if(version!==importVersion||inputSource!=='simbrief')return;let saved;try{saved=JSON.parse(raw);}catch{}if(saved&&saved.source&&saved.from&&saved.date){restore(saved);calculate();if($('error').textContent)throw Error($('error').textContent);}else if(version===importVersion&&inputSource==='simbrief')acceptSimbriefPlan(SimBrief.parse(raw));}catch(e){if(version!==importVersion)return;$('simbriefError').textContent=e.message;}finally{$('ofpFile').value='';}};$('saveSimbriefPlan').onclick=()=>{if(flight&&!$('error').textContent)downloadPlan();};$('resetSimbriefTime').onclick=()=>{resetImportedTime();calculate();};$('directFallback').onchange=calculate;$('showDirect').onchange=()=>{update();try{localStorage.setItem('dayflight',JSON.stringify(planState()));}catch{}};$('profileScrub').oninput=()=>applyScrubFraction(Number($('profileScrub').value)/1000);$('profilePanel').ontoggle=()=>{if($('profilePanel').open)updateProfile();};syncSourceUI();}
function profileColor(el){const stops=[[-25,[20,40,61]],[-18,[41,70,95]],[-12,[100,124,159]],[-6,[155,140,174]],[-.833,[213,163,140]],[8,[234,190,97]]];if(el<=stops[0][0])return 'rgb(20,40,61)';for(let i=1;i<stops.length;i++){if(el<=stops[i][0]){const [a,ac]=stops[i-1],[b,bc]=stops[i],f=(el-a)/(b-a);return `rgb(${ac.map((v,k)=>Math.round(v+(bc[k]-v)*f)).join(',')})`;}}return 'rgb(234,190,97)';}
function updateProfile(){
 const visible=!!flight?.route?.profileAvailable;$('profilePanel').hidden=!visible;if(!visible||!$('profilePanel').open)return;
 const c=$('profileCanvas'),w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;const dpr=window.devicePixelRatio||1;c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);const left=48,right=w-14,top=15,bottom=h-28,plotW=right-left,plotH=bottom-top;
 if(!profileCache||profileCache.flight!==flight||profileCache.w!==w||profileCache.h!==h||profileCache.dpr!==dpr){const layer=document.createElement('canvas');layer.width=c.width;layer.height=c.height;const q=layer.getContext('2d');q.scale(dpr,dpr);q.fillStyle='#f4f6ef';q.fillRect(0,0,w,h);const max=Math.max(10000,...flight.samples.map(s=>s.altitude||0)),ceiling=Math.ceil(max/10000)*10000,y=alt=>bottom-alt/ceiling*plotH;const gradient=q.createLinearGradient(left,0,right,0);for(let i=0;i<=100;i++){const sample=flight.samples[Math.round(i/100*(flight.samples.length-1))];gradient.addColorStop(i/100,profileColor(sample.el));}q.fillStyle=gradient;q.fillRect(left,top,plotW,plotH);q.font='11px sans-serif';q.textAlign='right';for(let alt=0;alt<=ceiling;alt+=10000){q.fillStyle='#567268';q.fillText(alt===0?'0':`${alt/1000}k`,left-7,y(alt)+4);q.strokeStyle='#ffffff35';q.beginPath();q.moveTo(left,y(alt));q.lineTo(right,y(alt));q.stroke();}q.strokeStyle='#f9fff1';q.lineWidth=2;q.shadowColor='#082c3d';q.shadowBlur=3;q.beginPath();let started=false;for(const s of flight.samples){if(s.altitude===null||s.altitude===undefined){started=false;continue;}const x=left+s.f*plotW;if(started)q.lineTo(x,y(s.altitude));else{q.moveTo(x,y(s.altitude));started=true;}}q.stroke();q.shadowBlur=0;for(const s of flight.segments){q.fillStyle=COLORS[s.cat];q.fillRect(left+s.start*plotW,bottom-5,(s.end-s.start)*plotW,5);}q.fillStyle='#567268';q.textAlign='left';q.fillText('Takeoff',left,h-8);q.textAlign='center';q.fillText(duration(flight.ms/2),left+plotW/2,h-8);q.textAlign='right';q.fillText('Touchdown',right,h-8);q.font='10px sans-serif';q.textAlign='center';for(const f of flight.route.fixes){if(!/^(TOC|TOD|T\/C|T\/D)$/.test(f.id))continue;const x=left+f.elapsed/flight.route.durationSec*plotW;q.fillStyle='#ffffffdd';q.fillRect(x-14,top+3,28,15);q.fillStyle='#274c4c';q.fillText(f.id,x,top+14);}profileCache={flight,w,h,dpr,layer,ceiling};}
 g.drawImage(profileCache.layer,0,0,w,h);const p=routePoint(progress),x=left+progress*plotW;g.strokeStyle='#fcfff5';g.lineWidth=1.5;g.beginPath();g.moveTo(x,top);g.lineTo(x,bottom);g.stroke();if(p.altitude!==null){g.fillStyle='#fff3c0';g.strokeStyle='#214e4b';g.beginPath();g.arc(x,bottom-p.altitude/profileCache.ceiling*plotH,4,0,2*Math.PI);g.fill();g.stroke();}$('profileScrub').value=Math.round(progress*1000);const readout=`${duration(progress*flight.ms)} elapsed · ${p.altitude===null?'Altitude unavailable':Math.round(p.altitude).toLocaleString()+' ft'} · ${p.from} → ${p.to}${p.airway?' via '+p.airway:''} · ${LIGHT_NAMES[category(elevation(p.lat,p.lon,solar(flight.start+progress*flight.ms)))]}`;$('profileReadout').textContent=readout;$('profileScrub').setAttribute('aria-valuetext',readout);
}
